export type ActiveContext = RequestContext;
import type {RequestContext} from './context.ts';
export function createContext(value: string, userId: string): RequestContext {return {requestId:value,userId};}
export function forkContext(context: RequestContext, suffix: string): RequestContext {return {...context, requestId: context.requestId+'/'+suffix};}
export interface Job {requestId: string; name: string;}
export function auditLabel(requestId: string) {return 'job:'+requestId;}
import type {RequestContext} from './context.ts';
import {auditLabel} from './job-types.ts';
import type {Job} from './job-types.ts';
export function describeJob(job: Job, context: RequestContext) {return {requestId:job.requestId,trace:context.requestId,audit:auditLabel(job.requestId),name:job.name};}
import type {ActiveContext as Context} from './context.ts';
export function logFields(context: Context) {const {requestId,userId}=context;return {requestId,userId};}
import type {RequestContext} from './context.ts';
export function headers(context: RequestContext) {return {'x-request-id':context.requestId};}
import type {ActiveContext} from './context.ts';
export function response(context: ActiveContext, payload: unknown) {return {requestId:context.requestId,payload};}
import {forkContext} from './context-factory.ts';
import type {RequestContext} from './context.ts';
import type {Job} from './job-types.ts';
import {describeJob} from './jobs.ts';
export function work(context: RequestContext, job: Job) {const child=forkContext(context,'worker');return describeJob(job,child);}
import {createContext} from './context-factory.ts';
import {headers} from './middleware.ts';
import {logFields} from './logging.ts';
import {response} from './response.ts';
import {work} from './worker.ts';
