import assert from 'node:assert/strict';
import {describe, test} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {auditLabel} from '../src/job-types.ts';
import {work} from '../src/worker.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {record0} from '../src/catalog/record0.ts';

describe('end-to-end propagation', () => {
  test('trace identifier reaches every stage with context rename', () => {
    const job = {requestId: 'job-xyz-100', name: 'data-sync'};
    const result = handle('trace-route-42', 'user-alpha', job);

    // RequestContext should have traceId, not requestId
    assert.equal(result.context.traceId, 'trace-route-42');
    assert.equal(result.context.userId, 'user-alpha');
    assert.equal('requestId' in result.context, false);
    assert.equal(result.context.requestId, undefined);

    // Middleware headers
    assert.equal(result.headers['x-request-id'], 'trace-route-42');

    // Logging fields
    assert.equal(result.logs.requestId, 'trace-route-42');
    assert.equal(result.logs.userId, 'user-alpha');

    // Response body
    assert.equal(result.body.requestId, 'trace-route-42');

    // Worker payload with forked trace suffix
    assert.equal(result.body.payload.trace, 'trace-route-42/worker');

    // Unrelated Job identifier in worker payload
    assert.equal(result.body.payload.requestId, 'job-xyz-100');
    assert.equal(result.body.payload.name, 'data-sync');
    assert.equal(result.body.payload.audit, 'job:job-xyz-100');
  });

  test('context creation and non-mutation behavior with forkContext', () => {
    const root = createContext('root-trace', 'user-1');
    assert.equal(root.traceId, 'root-trace');
    assert.equal(root.userId, 'user-1');
    assert.equal('requestId' in root, false);

    const child = forkContext(root, 'stage-a');
    assert.equal(child.traceId, 'root-trace/stage-a');
    assert.equal(child.userId, 'user-1');
    assert.equal('requestId' in child, false);

    // Verify non-mutation of parent context
    assert.equal(root.traceId, 'root-trace');

    const grandchild = forkContext(child, 'stage-b');
    assert.equal(grandchild.traceId, 'root-trace/stage-a/stage-b');
    assert.equal(child.traceId, 'root-trace/stage-a');
  });

  test('traceSummary and plugin consumption preserve traceId', () => {
    const ctx = createContext('summary-trace-99', 'user-plugins');
    const summary = traceSummary(ctx);

    assert.equal(summary.length, 8);
    summary.forEach((item, index) => {
      assert.equal(item.requestId, 'summary-trace-99');
      assert.equal(item.tag, `plugin${index}`);
      assert.equal(item.user, 'user-plugins');
    });
  });
});

describe('unrelated job identifier', () => {
  test('Job.requestId and auditLabel remain distinct from trace identifier', () => {
    const ctx = createContext('ctx-trace-555', 'user-beta');
    const job = {requestId: 'job-distinct-888', name: 'reindex'};

    const described = describeJob(job, ctx);
    assert.equal(described.requestId, 'job-distinct-888');
    assert.equal(described.trace, 'ctx-trace-555');
    assert.equal(described.audit, 'job:job-distinct-888');
    assert.equal(described.name, 'reindex');

    assert.equal(auditLabel('custom-audit-id'), 'job:custom-audit-id');

    const workerResult = work(ctx, job);
    assert.equal(workerResult.requestId, 'job-distinct-888');
    assert.equal(workerResult.trace, 'ctx-trace-555/worker');
    assert.equal(workerResult.audit, 'job:job-distinct-888');
    assert.equal(workerResult.name, 'reindex');
  });

  test('catalog RequestContext and requestId remain unaffected', () => {
    const catalogCtx = {requestId: 'catalog-req-001', category: 'items'};
    const record = record0(catalogCtx);
    assert.equal(record.requestId, 'catalog-req-001');
    assert.equal(record.category, 'items');
    assert.equal(record.label, 'record0:catalog-req-001');
  });
});

